learn=[('Compare prompt input types', 'Pass a string for a one-shot query or an AsyncIterable of SDKUserMessage objects for a long-lived interactive query. Both still produce an asynchronous output stream; input mode and output streaming are separate concepts.'), ('Keep conversation context deliberately', 'One streaming Query naturally retains its session context. Independent string queries start separate sessions. An explicit resume session ID can continue a persisted string session; continue selects the latest matching session instead.'), ('Bridge the UI with a bounded queue', 'A FIFO inbox wakes its waiting generator. This classroom host waits for each actual result before yielding the next queued message, making ordering visible and avoiding merged queued turns. Closing the queue releases idle waits.'), ('Send an actual image follow-up', 'The SDK message carries text and a real base64 PNG block. Inspect the supplied architecture image, send it after the first result and compare the agent’s actual visual answer with the image.'), ('Interrupt and control the live query', 'Use interrupt during an actual delayed Read, then continue the same Query. Await setPermissionMode acknowledgement before the next input. New chat starts a fresh Query and session; Finish closes the input queue.'), ('Handle errors and choose the right lifetime', 'Drain a string query loop so an exception after error_max_turns is caught. A streaming query can remain alive after the cap result and accept a recovery message. One-shot work suits short-lived hosts; interactive queues need a process and explicit cleanup.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3135\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. Windows may require Git Bash. Python is needed only to regenerate pages. The image fixture is bundled.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter the app, install locked dependencies, preserve an existing .env and enter your model key privately.', 'cd .\\agent-sdk\\lesson35-streaming-input\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open and open port 3135. Navigate between the lab, concepts, setup, UML and code walkthrough.', 'npm start\n# http://127.0.0.1:3135'), ('Compare strings and chat context', 'Run String, Independent sessions and Explicit resume. In Interactive chat wait for READY, send the supplied follow-up, read the actual remembered word and click Finish input. New chat starts a fresh Query.', 'npm run sample:env -- single\nnpm run sample:env -- isolated\nnpm run sample:env -- resume\nnpm run sample:env -- stream-chat --scripted'), ('Queue messages, images and controls', 'Queue two follow-ups while the first turn is active. In Image inspect the real PNG and send it after READY_IMAGE. In Interrupt click Stop while the delayed Read is pending; the same Query then accepts recovery. In Setter wait for READY_CONTROL and click the setter button. The --scripted flag explicitly automates these classroom actions only for CLI/tests.', 'npm run sample:env -- queued --scripted\nnpm run sample:env -- image --scripted\nnpm run sample:env -- interrupt --scripted\nnpm run sample:env -- setters --scripted'), ('Inspect cap errors and try terminal chat', 'The cap comparison drains the string loop, records its result and exception, and then shows a capped streaming turn recovering on the same Query. In terminal chat wait for READY, type a follow-up and enter /exit to close the input queue.', 'npm run sample:env -- caps --scripted\nnpm run terminal\n# Ask the terminal for the remembered classroom word.\n# Enter /exit when finished.\nnpm test')]
specs=[('Validate the selected input experiment', 'src/modes.ts', 'export function validateConfig', 'Accept a named classroom experiment. The browser cannot replace SDK options, tools or filesystem scope.', 0, 1, 7), ('Bound and enqueue FIFO input', 'src/queue.ts', 'push(value: T)', 'A bounded inbox preserves queued messages and wakes a waiting consumer. Reject overflow and writes after closure.', 0, 1, 10), ('Wait for input without losing wakeups', 'src/queue.ts', 'take(): Promise', 'A message buffered before the await is still consumed. Closing the queue wakes an idle consumer with null.', 1, 2, 9), ('Call query with a string', 'src/agent.ts', 'const q = query', 'A string query is drained to completion inside try/catch. Breaking at the first result would miss an exception raised after an error result.', 1, 3, 8), ('Resume an explicit persisted session', 'src/agent.ts', 'if (c.mode === "isolated"', 'Compare another independent string query with explicit resume of the actual prior session ID. The disposable workspace persists until both queries finish.', 1, 3, 9), ('Yield actual SDKUserMessage objects', 'src/agent.ts', 'yield {', 'An async generator yields the real message shape, including user role, content, null parent tool-use ID and the required session field.', 2, 3, 8), ('Gate the next yield on an actual result', 'src/agent.ts', 'if ((await gate.take())', 'The classroom generator waits for result acknowledgement before taking the next message. This explicit host policy makes each queued follow-up produce a visible turn.', 3, 2, 8), ('Send the actual PNG attachment', 'src/image.ts', 'return [', 'The image follow-up contains text plus real base64 image bytes. The browser displays the same bundled PNG and the actual model reads its visual marker.', 2, 3, 12), ('Route a bounded browser action', 'src/controls.ts', 'const handler = active.get', 'The action POST carries a live run capability. Invalid actions and stale IDs cannot control another run.', 0, 1, 6), ('Interrupt the live Query', 'src/agent.ts', 'interruptTask = active.interrupt();', 'Await the real interrupt acknowledgement during the delayed Read, then accept a recovery message on the same Query.', 0, 3, 5), ('Await a live permission-mode setter', 'src/agent.ts', 'await active.setPermissionMode', 'Wait for the actual setter acknowledgement before enqueuing the follow-up. Acknowledgement is reported separately from initialization metadata.', 1, 3, 5), ('Compare capped results and streaming recovery', 'src/agent.ts', 'if (c.mode === "caps" && streamTurns === 1)', 'A capped streaming result leaves the Query alive for a tool-free recovery message. The string path has already recorded the capped result and following exception.', 3, 2, 8), ('Close queues and clean the session', 'src/agent.ts', 'registration.close();', 'Remove the run capability, abort remaining work, close the SDK Query and clean only the verified temporary workspace. Finish releases idle input waits.', 1, 4, 6)]
document('/','Streaming input. <em>Keep the conversation.</em>','Compare string prompts, queued messages, images and live SDK controls.','<div class="flow"><div><b>01 · Send</b><p>String or queued message</p></div><span>→</span><div><b>02 · Yield</b><p>The SDK consumes actual input</p></div><span>→</span><div><b>03 · Continue</b><p>Inspect results and session identity</p></div></div><section class="panel" id="controls"><h2>Explore streaming input</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Input experiment</label><select id="mode"><option value="single">String · one question and result</option><option value="isolated">Strings · independent sessions</option><option value="resume">String · explicit session resume</option><option value="stream-chat">Streaming · interactive chat</option><option value="queued">Streaming · queue two follow-ups</option><option value="image">Streaming · actual image follow-up</option><option value="interrupt">Streaming · interrupt and recover</option><option value="setters">Streaming · live permission-mode setter</option><option value="caps">Compare · capped string and streaming recovery</option></select><button id="run" class="primary" disabled>Run input experiment →</button><p class="meta">Every result comes from the real SDK. Interactive modes wait for your buttons. Chat accepts up to six messages; Finish closes input. Each run has a six-minute host timeout and a $0.45 SDK budget threshold.</p></section><section class="step" id="chat-controls"><h2>Live session controls</h2><p id="phase" class="note" aria-live="polite">Choose an experiment.</p><p id="scripted" class="meta">Browser controls · explicit student actions</p><p class="meta">Run capability: <span id="run-id">—</span></p><label id="message-label" for="message-input">Your follow-up</label><textarea id="message-input" rows="2" maxlength="1000">What classroom word did I ask you to remember? Reply with the exact word only, or UNKNOWN if it is absent from this conversation. Do not use tools.</textarea><div class="actions"><button id="send-message" class="primary">Send follow-up</button><button id="queue-two" class="primary">Queue SECOND and THIRD</button><button id="send-image" class="primary">Send actual image</button><button id="stop-turn" class="primary">Stop current turn</button><button id="apply-mode" class="primary">Set dontAsk and continue</button><button id="finish-chat">Finish input</button><button id="new-chat">New chat · fresh Query</button></div><p id="control-notice" class="meta" aria-live="polite"></p><pre class="json-view"><code id="control-ack" class="language-json">{}</code></pre></section><figure class="step" id="image-preview" hidden><h2>The actual image attachment</h2><img src="/message-diagram.png" alt="Classroom architecture image with three labelled boxes and a printed visual marker"><figcaption>This bundled PNG is sent as real image content. The text prompt does not contain its printed marker.</figcaption></figure><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="conversation" aria-live="polite"></div></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Compare the prompt type, explicit resume and actual session IDs. Streaming input is distinct from streaming output.</p></section></div><section class="step" id="results-panel"><h2>Actual result and session history</h2><div class="table"><table><thead><tr><th>Query</th><th>Input</th><th>Turn</th><th>Status</th><th>Session ID</th></tr></thead><tbody id="result-history"></tbody></table></div></section><section class="step" id="observation-panel"><h2>Queue and control observations</h2><label for="observation-select">Inspect an actual observation</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre><details><summary>Complete observed sequence</summary><pre class="json-view"><code id="trace" class="language-json">[]</code></pre></details></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section><section class="step" id="exception-panel"><h2>Observed exceptions and native tool feedback</h2><p id="exception-notice" class="meta"></p><pre class="json-view"><code id="exception" class="language-json">{}</code></pre><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>A string query can yield a capped result and then throw. The comparison preserves both observations.</p></section><details class="step"><summary>Configuration and SDK initialization</summary><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre></details>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Choose an input lifetime and inspect actual session continuity.',cards(learn))
