for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">This diagram groups the string and streaming alternatives. A host FIFO queue feeds the generator, while the SDK owns the actual agent session. The host waits for each result before yielding the next message.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked input workflow steps"></div>'+walk)

reference=[('Input and output are separate', 'A string prompt still returns an asynchronous SDK output iterator. Streaming input describes how user messages enter the query, not whether response text is streamed. Partial-output rendering belongs to the next lesson.'), ('Host queue policy', 'This app gates each yielded message on the prior actual result. Without that policy, an application that eagerly yields several inputs may see different batching or turn boundaries. The queue and SDK session are distinct layers.'), ('Session lifetime and resume', 'Natural multi-turn context comes from one live streaming Query. String prompts can still resume a persisted session. This app uses an explicit actual session ID instead of continue, which selects the latest matching conversation. Persistence is enabled only for the resume comparison.'), ('Images', 'Single string prompts do not directly carry image blocks. The bundled image is sent as base64 image/png in an SDKUserMessage. Its printed marker is absent from the text instruction, and actual model output provides visual evidence.'), ('Interrupt versus closing input', 'interrupt asks the SDK to stop its current turn; closing the queue ends future input. The interruption demo waits for a real delayed Read and then recovers on the same Query. New chat starts a fresh Query; /clear is a separate SDK slash-command mechanism.'), ('Actual control acknowledgement', 'The setter example changes default to dontAsk and awaits setPermissionMode. It exposes only a fixed Read and keeps its allow rule. The resulting Read is not evidence of unrestricted access or a model switch. setModel is another available streaming control described in the source presentation.'), ('Cap and exception handling', 'The string loop must be drained to observe its exception after error_max_turns. The streaming comparison records the same cap result without a thrown stream error, then sends a tool-free recovery message. Budget and turn limits remain distinct controls.'), ('Scope and costs', 'Only the disposable lesson.txt Read is available; no edits, shell commands or subagents. A $0.45 SDK budget threshold is not a prepaid cap. Interactive chat is bounded to six inputs and a six-minute host lifetime. Secrets, dependencies and teaching media remain excluded from Git.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 35 · Streaming input versus single message\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson35-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson35-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson35-streaming-input`. Open http://127.0.0.1:3135 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK streaming-input documentation](https://code.claude.com/docs/en/agent-sdk/streaming-vs-single-mode)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for offline boundaries, review lifecycle, workspace and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 35 pages and thirteen source-linked UML steps.')

(PUBLIC/"style.css").write_text((PUBLIC/"style.css").read_text(encoding="utf-8")+'\n#conversation{max-height:620px;overflow:auto}.chat-message{padding:20px;border:1px solid var(--line);border-radius:16px;margin:14px 0;background:var(--soft)}.chat-message strong{display:block;margin-bottom:10px;color:#087fff}.chat-message .markdown-body{font-size:22px;line-height:1.6}.chat-message.user{background:var(--paper)}#chat-controls textarea{min-height:110px}#image-preview{margin-left:0;margin-right:0}#image-preview img{display:block;width:100%;max-width:960px;height:auto;margin:auto}#image-preview figcaption{font-size:20px;margin-top:18px}.json-view{max-height:420px}#conversation:empty:before{content:"Actual student inputs and SDK responses will appear here.";color:var(--muted)}\n',encoding="utf-8")
